import numpy as np

def construct():
    # Construct the [17, 8, 6] code by shortening the [18, 9, 6] extended quadratic residue code.
    # The [17, 9, 5] QR code is generated by a matrix G.
    # We keep only codewords with even weight (parity bit 0 in the extension).
    
    n = 17
    k = 9
    
    # Quadratic residues modulo 17 (excluding 0)
    residues = set((i * i) % n for i in range(1, n))
    
    # Generator matrix for the [17, 9, 5] QR code
    G = np.zeros((k, n), dtype=np.int8)
    G[0, :] = 1
    for i in range(1, k):
        for j in range(n):
            if (j - i) % n in residues:
                G[i, j] = 1
    
    # Generate all 2^9 possible codewords
    # masks: (512, 9)
    masks = np.array([(m >> i) & 1 for i in range(k) for m in range(1 << k)]).reshape(-1, k)
    
    # Compute codewords: C = masks @ G % 2
    # Using integer arithmetic for speed, then mod 2
    C = (masks @ G) % 2
    
    # Filter for even weight (shortening the extended code)
    weights = C.sum(axis=1)
    even_mask = (weights % 2 == 0)
    
    # Convert binary vectors to integers
    # Column j corresponds to bit j (2^j)
    powers = np.array([1 << j for j in range(n)], dtype=np.int64)
    words = C[even_mask] @ powers
    
    return [int(w) for w in words]
